contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seedDrugs, uint256 eth) public payable {
        require(seedDrugs > 0);
        require(seedDrugs <= eth);
        require(eth > 0);
        require(address(this).balance >= eth);

        c.seedMarket{value: seedDrugs}(seedDrugs);

        uint256 marketBefore = c.marketDrugs();
        uint256 ceoBalBefore = c.ceoAddress().balance;
        uint256 claimedBefore = c.claimedDrugs(address(this));

        bool reverted;
        try c.buyDrugs{value: eth}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 expectedFee = eth * 4 / 100;
        uint256 marketAfter = c.marketDrugs();
        uint256 ceoBalAfter = c.ceoAddress().balance;
        uint256 claimedAfter = c.claimedDrugs(address(this));

        assert(
            (reverted && ceoBalAfter == ceoBalBefore && marketAfter == marketBefore && claimedAfter == claimedBefore) ||
            (!reverted && ceoBalAfter == ceoBalBefore + expectedFee && marketAfter >= marketBefore && claimedAfter >= claimedBefore)
        );
    }
}

