contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seed, uint256 buyAmount) public payable {
        require(seed > 0, "seed must be positive");
        require(buyAmount > 0, "buyAmount must be positive");
        require(address(this).balance >= buyAmount, "insufficient balance");

        c.seedMarket{value: address(this).balance}(seed);

        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 marketBefore = c.marketDrugs();
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ceoBalanceBefore = c.ceoAddress().balance;

        c.buyDrugs{value: buyAmount}();

        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 marketAfter = c.marketDrugs();
        uint256 contractBalanceAfter = address(c).balance;
        uint256 ceoBalanceAfter = c.ceoAddress().balance;

        uint256 expectedFee = c.devFee(buyAmount);

        assert(claimedAfter - claimedBefore == c.calculateDrugBuy(buyAmount, contractBalanceBefore) - expectedFee);
    }

    receive() external payable {}
}
